export interface DocumentInstance {
  /**
   * P2.9 — REPLACES the `deleted` boolean, which was read in 12 places and written in none. ★★ A TIMESTAMP, not a flag: "when" answers a question a person will ask and `true` does not. ★ The staff_delete RLS policy went with it — a hard-delete permission nobody exercised, on the one table holding signed instruments.
   */
  archived_at: Timestamp | null;
  archived_by: string | null;
  assigned_to: Generated<string[]>;
  /**
   * P9.3. true when the frozen body differs from the template's. An instrument that differs from its template without a record is indistinguishable from a forgery.
   */
  body_overridden: Generated<boolean>;
  /**
   * B-4 (F794) — the session this document was raised for, if any. Replaces booking.document_instance_id (retired 0513) as the way booking history reaches its own agreement/form.
   */
  booking_id: string | null;
  builder: string;
  created_at: Generated<Timestamp>;
  /**
   * 05 §6 / §2b.2 — WHO WROTE IT. The writer disjunct of keystone.document_is_visible reads this and nothing else. Filled by src/documents/writes.mjs createInstance from the actorUserId that src/routes/writes.mjs:324 stamps AFTER spreading the body, so a request body can never name a writer. NULL = written before 0194 (no backfill is possible — nothing recorded it at the time); such a note is still reachable by the assigned coach and the Owner, which is fail-closed and agrees with 05 §6. ★ AUTHORSHIP IS NOT OWNERSHIP: this is NOT an ownerColumn for any entry in src/permissions/ownership.mjs — document is owned INDIRECTLY through subject_user_id (0071) and note is ownable:false (F584). db/gates/p1_ownership.mjs §8 asserts that, see 7.14 field 8(f).
   */
  created_by: string | null;
  /**
   * 14.11 — when a signer declined the instrument.
   */
  declined_at: Timestamp | null;
  executed_at: Timestamp | null;
  /**
   * When an unsigned sent instrument lapses. NULL = never. Set once at send from the tenant setting documents.signature_validity_days; never re-read from the setting afterwards.
   */
  expires_at: Timestamp | null;
  id: Generated<string>;
  /**
   * 14.11 — earliest instant the reminder sweep may next act on this instrument; read by system_reminder_read/system_reminder_write.
   */
  next_reminder_at: Timestamp | null;
  /**
   * 14.11 — capped 0-10 so a stuck sweep cannot mail a signer forever.
   */
  reminders_sent: Generated<number>;
  /**
   * P9.3. locked = the template's words unchanged · fill = variables filled in (DEFAULT, KS-8.2) · open = the sender departed from the template. A property of THIS send, not of the template.
   */
  send_mode: Generated<string>;
  sent_at: Timestamp | null;
  /**
   * 14.13 / G29 / CT-F07 — WHO shared it. NULL exactly when shared_with_client_at is NULL (share_pair
   *   CHECK). Filled by the share route from the acting staff user, never from the request body.
   */
  shared_by: string | null;
  /**
   * 14.13 / G29 / CT-F07 — WHEN a staff member shared this note with its own subject. NULL = never
   *   shared (the default for every existing row and every new one until a staff member acts). Read by
   *   keystone.document_is_visible's non-staff branch, which is the ONLY thing that gates a client
   *   reading a session note about themselves.
   */
  shared_with_client_at: Timestamp | null;
  state: Generated<string>;
  subject_user_id: string | null;
  /**
   * P18.9 / §M0 LAW 3 — the template BODY as it stood when this instrument was SENT. Frozen at send because that is the moment a person is shown the words; P15C.8's "a sent instrument never re-picks up its template" is only true if the copy happens here. ★ DISTINCT from template_snapshot, which is the whole instrument (body + price + disclosure) frozen at EXECUTE — writing a bare body into that column is refused by snapshot_is_readable, which is how the distinction was found.
   */
  template_body_snapshot: Json | null;
  template_id: string | null;
  template_snapshot: Json | null;
  tenant_id: string;
  /**
   * The instrument's own title, frozen at creation from the template name. NOT a join to document_template: template_id is nullable and a template rename would retitle an already EXECUTED instrument, which hard limit 3 forbids. Same family as line_item.name_snapshot.
   */
  title: string;
  type_id: string | null;
  updated_at: Generated<Timestamp>;
}

